const CLOUD_QUESTIONS = [
 /* --- Cloud Overview & Topology --- */
 {exam:"cloudadmin",cat:"cloudover",q:"In Splunk Cloud Platform, which does <b>Splunk</b> manage rather than the customer?",o:["The indexers, search heads, and platform upgrades","The universal forwarders installed on customer hosts","The customer's deployment server","The data inputs on customer-owned servers"],a:[0],e:"Splunk manages the indexing/search tier and platform <b>upgrades</b> (shared-responsibility model). The customer manages forwarders, their own inputs, and (if used) their own deployment server.",d:CL_GDI},
 {exam:"cloudadmin",cat:"cloudover",q:"A Cloud admin needs to change a setting that on-prem would mean editing a <code>.conf</code> file. In Splunk Cloud Platform they must instead use…",o:["SSH to the search head and edit the file","Splunk Web, the ACS API/CLI, or a Support ticket","<code>btool</code> on the indexer","The universal forwarder"],a:[1],e:"Cloud gives <b>no filesystem/CLI access</b>. Configuration changes go through <b>Splunk Web</b>, the <b>Admin Config Service (ACS)</b>, or a <b>Support ticket</b> for anything not self-serviceable.",d:CL_ACSCLI},
 {exam:"cloudadmin",cat:"cloudover",q:"What is the Admin Config Service (ACS) in Splunk Cloud Platform?",o:["A cloud-native API/CLI for self-service admin tasks without a Support ticket","A replacement for the universal forwarder","The Cloud Monitoring Console","A premium security app"],a:[0],e:"<b>ACS</b> is a cloud-native API (and CLI/Terraform provider) for <b>self-service</b> administration — indexes, HEC tokens, IP allow lists, limits, users, apps — without opening a Support ticket.",d:CL_ACS},
 {exam:"cloudadmin",cat:"cloudover",q:"How does an admin find whether their stack is the <b>Victoria</b> or <b>Classic</b> experience, and who controls it?",o:["Splunk Web &gt; Support &amp; Services &gt; About; Splunk assigns it and customers cannot change it themselves","Edit server.conf; the customer sets it","It's on the login page; Support toggles it on request","Run <code>splunk version</code>; it switches automatically"],a:[0],e:"Check <b>Support &amp; Services &gt; About</b> in Splunk Web. <b>Splunk assigns</b> the experience; customers can't switch it themselves.",d:CL_EXP,hard:true},
 {exam:"cloudadmin",cat:"cloudover",q:"On which Splunk Cloud experience do scripted and modular inputs run <b>directly on the search head</b>, with <b>no separate IDM required</b>?",o:["Classic","Victoria","Both","Neither — an IDM is always required"],a:[1],e:"<b>Victoria</b> runs scripted/modular inputs on the search head (no IDM). <b>Classic</b> requires a separate <b>Inputs Data Manager (IDM)</b> for those inputs.",d:CL_GDI,hard:true},
 {exam:"cloudadmin",cat:"cloudover",q:"Which task is <b>NOT</b> something a Splunk Cloud admin performs themselves?",o:["Creating an index","Installing a self-service Splunkbase app","Applying Splunk Cloud Platform version upgrades to the indexers","Managing users and roles"],a:[2],e:"<b>Splunk manages platform upgrades.</b> The admin self-services indexes, apps, users, and inputs — but not the underlying indexer/search-head upgrades.",d:CL_GDI},
 {exam:"cloudadmin",cat:"cloudover",q:"Which is a supported method for getting data into Splunk Cloud Platform?",o:["Forwarders, HEC, apps/add-ons, and the Inputs Data Manager (IDM)","Only universal forwarders","FTP upload directly to the indexer","SSH in and edit inputs.conf on the indexer"],a:[0],e:"The four supported paths are <b>forwarders, HTTP Event Collector (HEC), apps/add-ons, and the IDM</b>.",d:CL_GDI},
 /* --- Getting Data Into Cloud (highest weight) --- */
 {exam:"cloudadmin",cat:"cloudgdi",q:"To connect a universal forwarder to Splunk Cloud, an admin downloads a package. What is it and where is it obtained?",o:["<code>splunkclouduf.spl</code>, from Splunk Web &gt; Apps &gt; Universal Forwarder &gt; Download Universal Forwarder Credentials","<code>outputs.conf</code>, emailed by Splunk Support","A license file from the license manager","<code>indexes.conf</code>, from Splunkbase"],a:[0],e:"The <b>Universal Forwarder Credentials</b> package <code>splunkclouduf.spl</code> is downloaded from the <b>Universal Forwarder app</b> in Splunk Web.",d:CL_UFRECV},
 {exam:"cloudadmin",cat:"cloudgdi",q:"What does the <code>splunkclouduf.spl</code> credentials package contain?",o:["A Splunk app with <code>outputs.conf</code> and the TLS certificates to authenticate to your Cloud stack","A universal forwarder installer","A copy of your indexed data","A SAML metadata file"],a:[0],e:"It's a Splunk <b>app</b> bundling <b>outputs.conf + TLS certs</b> so the forwarder connects and authenticates to your Cloud indexers.",d:CL_UFRECV},
 {exam:"cloudadmin",cat:"cloudgdi",q:"After copying <code>splunkclouduf.spl</code> to a forwarder, how do you apply it?",o:["Run <code>splunk install app splunkclouduf.spl</code>, then restart the forwarder","Double-click it in Splunk Web on the indexer","Hand-edit it into system/local/outputs.conf","Upload it through HEC"],a:[0],e:"<b>Install it as an app</b> (<code>splunk install app ...</code>) and <b>restart</b> the forwarder; it lands under <code>etc/apps</code>.",d:CL_UFRECV},
 {exam:"cloudadmin",cat:"cloudgdi",q:"To send <b>parsed (event-based)</b> data to Splunk Cloud indexers, which is required?",o:["A universal forwarder on its own","A heavy forwarder or an IDM","HEC only","A deployment server"],a:[1],e:"A <b>UF forwards unparsed data</b>. Sending <b>parsed/event data</b> to Cloud requires a <b>heavy forwarder or IDM</b>.",d:CL_FWD,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"Which port must typically be open in the firewall for a <b>forwarder</b> to send data to Splunk Cloud Platform?",o:["8000","8089","9997","514"],a:[2],e:"<b>9997</b> is the default S2S receiving/forwarding port (Cloud enables the receiver by default). Don't confuse it with HEC on Cloud, which uses 443.",d:CL_NIX},
 {exam:"cloudadmin",cat:"cloudgdi",q:"On Splunk Cloud Platform, the default HTTP Event Collector (HEC) port is…",o:["8088","443","9997","8089"],a:[1],e:"Cloud HEC uses <b>443</b> (versus <b>8088</b> on Splunk Enterprise and Cloud free trials).",d:CL_HEC,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"A developer's HEC requests to Splunk Cloud (AWS) fail. They used <code>https://mystack.splunkcloud.com</code>. What's wrong?",o:["Cloud HEC requires the <code>http-inputs-</code> prefix, e.g. <code>http-inputs-mystack.splunkcloud.com</code>","HEC is disabled by default on Cloud","They must use port 8088","HEC only accepts UDP"],a:[0],e:"Cloud HEC URIs need the <b><code>http-inputs-</code></b> prefix (AWS) or data never reaches HEC.",d:CL_HEC,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"What is the Inputs Data Manager (IDM)?",o:["A Splunk-hosted component for scripted/modular (e.g. cloud API) inputs, removing customer-managed forwarder infrastructure","A customer-run deployment server","The Cloud Monitoring Console","A premium security app"],a:[0],e:"The <b>IDM</b> is Splunk-hosted for scripted/modular inputs. Required on <b>Classic</b>; not needed on <b>Victoria</b> (those inputs run on the SH).",d:CL_GDI},
 {exam:"cloudadmin",cat:"cloudgdi",q:"Which statement about the IDM is TRUE?",o:["It supports HEC inputs and self-service app install","It fully replaces a heavy forwarder because it parses data","It cannot do HEC, self-service app install, or receive unencrypted TCP, and does not parse like an HF","It is included on the Free Trial"],a:[2],e:"The IDM has <b>no HEC</b>, <b>no self-service app install</b> (Support uploads your app), no unencrypted TCP, isn't an HF replacement, and isn't on the Free Trial.",d:CL_GDI,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"After installing the credentials package, how do you verify a forwarder is sending to Cloud?",o:["Search in Splunk Web (e.g. a test index) and confirm the forwarder's host and expected sourcetypes appear","Look for a green light on the indexer","Run <code>btool</code> on the Cloud indexer","Call Support to confirm"],a:[0],e:"Verify by <b>searching</b> and confirming the forwarder's <b>host</b> and expected <b>sourcetypes</b> arrive. Best practice: point at a <b>test index</b> first.",d:CL_NIX},
 {exam:"cloudadmin",cat:"cloudgdi",q:"Which <code>outputs.conf</code> setting enables automatic TLS certificate renewal for forwarders to Splunk Cloud, and what is its default?",o:["<code>autoCertRotation = true</code>; default is <b>false</b> (off)","<code>sslRenew = on</code>; default true","<code>certRotate = auto</code>; default true","There is none — certs never expire"],a:[0],e:"<b><code>autoCertRotation = true</code></b> in the <code>[tcpout:&lt;group&gt;]</code> stanza; it's <b>off by default</b> and needs UF 9.3.0+ to Cloud 9.2.2406+.",d:CL_UFRECV,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"An admin wants to aggregate data through a middle tier before it reaches Cloud, to limit internet-facing hosts. What is this and the recommended ratio?",o:["An intermediate forwarding tier of heavy forwarders; 2:1 or greater intermediate forwarders to Cloud indexers","A second IDM; 1:1","A deployment server tier; 5:1","HEC relays; 10:1"],a:[0],e:"An <b>intermediate forwarding tier</b> (HFs) aggregates data; Splunk recommends <b>2:1 or greater</b> intermediate forwarders to Cloud indexers.",d:CL_FWD,hard:true},
 /* --- Index Management in Cloud --- */
 {exam:"cloudadmin",cat:"cloudidx",q:"How does a Splunk Cloud admin create a new index?",o:["Edit <code>indexes.conf</code> in <code>etc/system/local</code>","In Splunk Web (Settings &gt; Indexes &gt; New Index) or via the ACS API","SSH to an indexer and run a CLI command","Only by opening a Support ticket"],a:[1],e:"Cloud indexes are created in <b>Splunk Web</b> or via the <b>ACS API</b> — never by editing <code>indexes.conf</code> on disk.",d:CL_MANIDX},
 {exam:"cloudadmin",cat:"cloudidx",q:"Which two settings govern per-index data retention in Splunk Cloud?",o:["<code>frozenTimePeriodInSecs</code> and <code>coldToFrozenDir</code>","Max raw data size and Searchable retention (days)","Hot and warm bucket counts","License volume and user count"],a:[1],e:"In Cloud you set <b>Max raw data size</b> and <b>Searchable retention (days)</b>; whichever hits first rolls/deletes data by <b>whole buckets, oldest first</b>.",d:CL_MANIDX},
 {exam:"cloudadmin",cat:"cloudidx",q:"What is the difference between Dynamic Data Self-Storage (DDSS) and Dynamic Data Active Archive (DDAA)?",o:["DDSS moves expired data to the customer's own cloud storage (not searchable in Cloud); DDAA is a Splunk-managed archive you can restore and search","They are identical","DDSS is Splunk-managed; DDAA is customer-managed","Both keep data searchable in Cloud indefinitely"],a:[0],e:"<b>DDSS</b> = your own S3/GCS/Azure (not searchable in Cloud). <b>DDAA</b> = Splunk-managed archive, restorable. They <b>cannot both be active</b> on one index.",d:CL_DDAA,hard:true},
 {exam:"cloudadmin",cat:"cloudidx",q:"After restoring data from a Dynamic Data Active Archive (DDAA), how long is it searchable and does it count against your license?",o:["Searchable for 30 days (fixed), and it does NOT count against license or index retention","Permanently searchable, and it counts against license","24 hours only","Until you delete it, and it counts against license"],a:[0],e:"Restored DDAA data is searchable for <b>30 days (fixed, unchangeable)</b> and does <b>not</b> count against license/retention. The restore itself can take up to 24 hours.",d:CL_DDAA,hard:true},
 {exam:"cloudadmin",cat:"cloudidx",q:"Which is TRUE about removing data in Splunk Cloud?",o:["You SSH in and delete the bucket files","The <code>delete</code> search command frees disk space","Deleting an index removes all its data and is irreversible; the <code>delete</code> command only marks events unsearchable and does not free disk space","You can delete default and third-party indexes from the Indexes page"],a:[2],e:"There's no filesystem access. <b>Deleting an index</b> is final; the <b><code>delete</code></b> command (needs <code>delete_by_keyword</code>/<code>can_delete</code>) only makes events <b>unsearchable</b> and doesn't reclaim disk.",d:CL_DELETE,hard:true},
 {exam:"cloudadmin",cat:"cloudidx",q:"Which is TRUE about internal indexes (e.g. <code>_internal</code>, <code>_audit</code>) in Splunk Cloud?",o:["Their retention period cannot be modified","You can delete them from the Indexes page","They do not exist in Cloud","Their retention is unlimited and extendable"],a:[0],e:"Internal indexes exist in Cloud, but their <b>retention cannot be changed</b>.",d:CL_MANIDX},
 {exam:"cloudadmin",cat:"cloudidx",q:"Which tool monitors indexing and deployment health in Splunk Cloud (replacing the on-prem Monitoring Console)?",o:["The Distributed Management Console (DMC), edited freely","The Cloud Monitoring Console (CMC) — and you should not modify its dashboards","<code>btool</code>","The deployment server"],a:[1],e:"The <b>Cloud Monitoring Console (CMC)</b> is the Cloud health app. <b>Do not modify</b> its dashboards.",d:CL_CMC},
 {exam:"cloudadmin",cat:"cloudidx",q:"The CMC Overview 'Attention required' section surfaces which of these?",o:["Blocked indexer queues, sustained HEC 503s, missing forwarders, high skipped-search %, and peak SVC usage","Your monthly AWS invoice","Raw <code>.conf</code> file contents","Stored LDAP passwords"],a:[0],e:"CMC flags <b>blocked queues, HEC 503s, missing forwarders, skipped searches</b>, and shows <b>peak SVC usage</b> and storage.",d:CL_CMC},
 /* --- Config & Admin Access (ACS) --- */
 {exam:"cloudadmin",cat:"cloudconf",q:"Which role is the Splunk Cloud Platform administrator super-role required for index, app, and ACS operations?",o:["<code>admin</code>","<code>sc_admin</code>","<code>power</code>","<code>can_delete</code>"],a:[1],e:"In Cloud the super-admin role is <b><code>sc_admin</code></b> — not the on-prem <code>admin</code> role.",d:CL_ACSREF,hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"Which is TRUE about using the ACS API?",o:["It requires the <code>sc_admin</code> role and a bearer token, and is not supported on single-instance deployments","It needs SSH access to the indexer","It works only from the indexer CLI","It requires no authentication"],a:[0],e:"ACS needs the <b><code>sc_admin</code></b> role + a <b>JWT/bearer token</b>, and is <b>not supported on single-instance</b> deployments (needs SH or SHC).",d:CL_ACSREF,hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"Which can an admin self-service via ACS (no Support ticket)?",o:["IP allow lists, indexes, HEC tokens, select limits.conf settings, and users/roles","Physically replacing an indexer's disk","Rewriting Splunk's source code","Applying the platform version upgrade"],a:[0],e:"ACS self-services <b>IP allow lists, indexes, HEC tokens, a limits.conf subset, users/roles, apps</b>, and maintenance windows.",d:CL_ACSREF},
 {exam:"cloudadmin",cat:"cloudconf",q:"Which statement about editing <code>limits.conf</code> in Splunk Cloud is correct?",o:["You can edit any setting via SSH","ACS exposes only a <b>subset</b> of limits.conf settings (Victoria) — e.g. subsearch maxout/maxtime; anything outside the subset needs Support","limits.conf cannot be changed at all","It is edited in Splunk Web under Indexes"],a:[1],e:"ACS exposes a <b>Victoria-only subset</b> of <code>limits.conf</code> (view/edit/reset). Out-of-subset changes still require <b>Support</b>.",d:CL_ACSLIM,hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"In Victoria, globally-shared app assets across all search heads follow standard configuration precedence. A practical consequence is…",o:["Config precedence no longer matters in Cloud","Same-named lookups or knowledge objects across apps can collide (lexicographical ordering)","Every app is fully isolated, so nothing can collide","Precedence becomes random"],a:[1],e:"Standard <b>precedence / lexicographical ordering</b> still applies, so identically-named KOs across apps can <b>collide</b>.",d:CL_PRIVAPP,hard:true},
 /* --- Apps & Private Apps --- */
 {exam:"cloudadmin",cat:"cloudapps",q:"Which is TRUE about self-service app installation in Splunk Cloud?",o:["It requires the <code>sc_admin</code> role; most Splunkbase apps install directly from Splunk Web or ACS","Any user can install any app","All apps require a Support ticket","Apps can only be installed on the IDM"],a:[0],e:"Self-service install requires <b><code>sc_admin</code></b>; the large majority of Splunkbase apps install from <b>Splunk Web</b> or <b>ACS</b>.",d:CL_INSTALL},
 {exam:"cloudadmin",cat:"cloudapps",q:"Before a private app can be self-service installed in Splunk Web, its AppInspect report must show…",o:["0 Failures, 0 Errors, and 0 Manual Checks (any Manual Check forces a Support ticket)","At least one warning","Nothing — vetting is skipped in Cloud","A passing score of 70%"],a:[0],e:"Self-service needs <b>0 Failures, 0 Errors, 0 Manual Checks</b>. Any <b>Manual Check</b> routes the app to <b>Support</b> for manual vetting.",d:CL_PRIVAPP,hard:true},
 {exam:"cloudadmin",cat:"cloudapps",q:"Which app scenario REQUIRES contacting Splunk Support rather than self-service install?",o:["A common Splunkbase add-on on Victoria","A premium app such as Enterprise Security or ITSI","A private app that passes AppInspect cleanly","Any app under 128 MB"],a:[1],e:"<b>Premium apps (ES/ITSI)</b>, IDM installs, non-vetted apps, and apps with &gt;0 manual checks require <b>Support</b>.",d:CL_INSTALL},
 {exam:"cloudadmin",cat:"cloudapps",q:"How must a private (custom) app for Splunk Cloud be packaged?",o:["As a <code>.spl</code>/<code>.tar.gz</code> ≤128 MB with dynamic dependencies only (no static deps)","As a Windows <code>.exe</code>","Uploaded through HEC","Any size, with static dependencies allowed"],a:[0],e:"Private apps: <b><code>.spl/.tar/.tgz</code>, ≤128 MB, dynamic dependencies only</b>. Cloud auto-runs <b>AppInspect</b> on upload.",d:CL_PRIVAPP,hard:true},
 {exam:"cloudadmin",cat:"cloudapps",q:"Which is TRUE about updating apps in Splunk Cloud?",o:["You can roll back to a previous version with one click","After updating you cannot roll back — you must uninstall then reinstall the older package; ES/ITSI can't be self-service updated","All updates require Support","Updates are automatic and silent"],a:[1],e:"There's <b>no self-service rollback</b> — reinstall the older package. <b>ES/ITSI updates need Support</b>.",d:CL_INSTALL,hard:true},
 {exam:"cloudadmin",cat:"cloudapps",q:"On the Victoria experience, a self-service app install lands on which components?",o:["Only one standalone search head","All search heads / SHC members (including premium ES/ITSI SHs) and indexers","Only the IDM","Only the deployment server"],a:[1],e:"On <b>Victoria</b> (no IDM), an installed app auto-deploys across <b>all search heads</b> — including premium — plus indexers.",d:CL_PRIVAPP},
 /* --- Working with Cloud Support --- */
 {exam:"cloudadmin",cat:"cloudsupport",q:"Before opening a Splunk Cloud Support case, an admin should first…",o:["Restart all forwarders","Self-triage with the CMC dashboards and search internal indexes (<code>index=_internal</code>, <code>index=_audit</code>) to isolate the problem","Delete the affected index","Reinstall Splunk"],a:[1],e:"<b>Isolate first</b>: use the <b>CMC</b> and search <code>_internal</code>/<code>_audit</code> before contacting Support.",d:CL_CMC},
 {exam:"cloudadmin",cat:"cloudsupport",q:"How are Splunk Cloud Support cases submitted?",o:["Through the Splunk Support Portal (online case submission)","By editing a <code>.conf</code> file","Via the deployment server","By emailing the indexer directly"],a:[0],e:"Cases are opened through the <b>Splunk Support Portal</b>.",d:CL_SUPPORT},
 {exam:"cloudadmin",cat:"cloudsupport",q:"Which is TRUE about Splunk support severity coverage?",o:["P1 (system inaccessible / majority unusable) is 24×7; Standard support covers P1 while Premium adds P2","All severities are 24×7 on every plan","P4 receives the fastest response","Severity has no effect on response"],a:[0],e:"<b>P1</b> = 24×7 with a fast initial response; <b>Standard</b> covers P1 and <b>Premium</b> adds P2. Verify exact SLA numbers against the customer's plan.",d:CL_SUPPORT,hard:true},
 {exam:"cloudadmin",cat:"cloudsupport",q:"On the <b>Classic</b> experience, after creating a new index that IDM-based inputs must write to, what extra step is required?",o:["Nothing — it is automatic","Open a Support case to sync the index to your IDM","Restart the search head","Re-download the credentials package"],a:[1],e:"On <b>Classic</b>, you must open a <b>Support case to sync the new index to the IDM</b>. Victoria has no IDM, so this doesn't apply.",d:CL_MANIDX,hard:true},
 /* --- Forwarder Management (Cloud) --- */
 {exam:"cloudadmin",cat:"cloudfwd",q:"Which is TRUE about the deployment server in Splunk Cloud Platform?",o:["Splunk Cloud provides a managed deployment server for you","Splunk Cloud does NOT provide one — the customer hosts it (on-prem or in their own cloud) to manage forwarders","The IDM acts as your deployment server","Forwarders cannot be centrally managed in Cloud"],a:[1],e:"<b>Splunk Cloud does not provide a deployment server.</b> The <b>customer runs their own</b> (on-prem or in their cloud) to push deployment-apps to forwarder clients — a common exam trap.",d:CL_GDI,hard:true},
 {exam:"cloudadmin",cat:"cloudfwd",q:"What is the efficient way to install the Cloud credentials package and inputs across hundreds of universal forwarders?",o:["Manually SSH to each forwarder","Place the app in <code>etc/deployment-apps</code> on a (customer-run) deployment server and push it to deployment clients","Email the <code>.spl</code> to each server owner","Send it through HEC"],a:[1],e:"Use a <b>customer-run deployment server</b>: stage <code>splunkclouduf.spl</code> + inputs as <b>deployment-apps</b> and push to the forwarder clients.",d:CL_FWD},
 /* --- added: cross-checked against real SPLK-1005 practice sets --- */
 {exam:"cloudadmin",cat:"cloudgdi",q:"In a managed Splunk Cloud environment, how does an application team get an HTTP Event Collector (HEC) token?",o:["Any token works — HEC accepts it and the data just lands in the wrong index if it's off","The <b>admin</b> generates a token when configuring the HEC input (Settings &gt; Data Inputs &gt; HEC &gt; New Token) and provides it to the app developers","The app developers generate the token and hand it to the admin to apply","You open a Support case for every new HEC input and Splunk returns a token"],a:[1],e:"The <b>admin creates the HEC token</b> in Splunk Web (or via ACS) and <b>gives it to the developers</b> to use. Tokens aren't supplied by developers, and standard HEC tokens don't need a per-input Support case.",d:CL_HEC,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"Which is <b>NOT</b> a valid path from which Splunk executes scripted inputs?",o:["<code>$SPLUNK_HOME/etc/system/bin</code>","<code>$SPLUNK_HOME/etc/apps/&lt;app&gt;/bin</code>","<code>$SPLUNK_HOME/etc/scripts/local</code>","<code>$SPLUNK_HOME/bin/scripts</code>"],a:[2],e:"Splunk runs scripts only from <code>etc/system/bin</code>, <code>etc/apps/&lt;app&gt;/bin</code>, and <code>bin/scripts</code>. <b><code>etc/scripts/local</code> is not a valid script path.</b>",d:"https://docs.splunk.com/Documentation/Splunk/latest/AdvancedDev/ScriptSetup",hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"What does <code>followTail = 1</code> do for a monitor input in <code>inputs.conf</code>?",o:["Pauses the monitor when the queue is full","Prevents pre-existing content from being ingested — it starts at the <b>end</b> of the file (like <code>tail</code>), reading only new data","Ingests new content first, then goes back and reads older events","Only writes a checkpoint without reading any data"],a:[1],e:"<code>followTail = 1</code> begins monitoring at the <b>end of the file</b>, so only data written <b>after</b> monitoring starts is indexed — pre-existing content is skipped. (It's discouraged for general use.)",d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories",hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"Which statement about <code>SEDCMD</code> data transformations is TRUE?",o:["It is configured in <b>props.conf only</b> (no transforms.conf) and applies sed-style masking/replacement to raw data at index time","It must be configured in <b>both</b> props.conf and transforms.conf","It changes the sourcetype on a per-event basis","It matches on a regex of the sourcetype or host to route events"],a:[0],e:"<b><code>SEDCMD</code> lives entirely in <code>props.conf</code></b> and does sed-style substitution (masking/replacing) of raw data. The trap: a <i>REGEX</i>-based transform needs <b>both</b> props.conf and transforms.conf — <code>SEDCMD</code> does not.",d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Anonymizedata",hard:true},
 {exam:"cloudadmin",cat:"cloudsupport",q:"A Splunkbase app you want shows <b>&ldquo;Request Install&rdquo;</b> instead of a self-service install button. What's the correct action?",o:["Tune the search yourself","<b>Contact Splunk Cloud Support</b> to have the app installed","Run the <code>delete</code> command first","Create a role that mirrors <code>sc_admin</code>"],a:[1],e:"A <b>&ldquo;Request Install&rdquo;</b> app isn't self-service vetted, so you <b>open a Support case</b> to have it installed. Search tuning, <code>delete</code>, and role creation are all self-service.",d:CL_INSTALL,hard:true},
 {exam:"cloudadmin",cat:"cloudfwd",q:"Where should you deploy input apps/add-ons that aren't permitted to run on Splunk Cloud?",o:["On a customer-managed forwarder — a <b>UF for simple inputs</b>, or an <b>HF/IDM for modular or scripted inputs</b> that need a full instance","On a heavy forwarder only","On a universal forwarder only","They can't run anywhere — Cloud blocks them entirely"],a:[0],e:"Run disallowed input apps on a <b>customer-managed forwarder</b>. Basic file/monitor inputs work on a <b>UF</b>; <b>modular/scripted inputs that need Python or a full instance go on an HF or the IDM</b>.",d:CL_FWD,hard:true},
 /* --- added: second practice-set cross-check --- */
 {exam:"cloudadmin",cat:"cloudgdi",q:"When monitoring a directory that contains <b>mixed file types</b>, which setting should be <b>omitted</b> from inputs.conf and instead overridden in props.conf?",o:["<code>sourcetype</code>","<code>host</code>","<code>source</code>","<code>index</code>"],a:[0],e:"Hardcoding one <code>sourcetype</code> in inputs.conf would force <b>every</b> file in the directory to that type. Omit it, let Splunk auto-assign, and override per-source in <b>props.conf</b> (e.g. <code>[source::.../*.log]</code>). <code>host</code>, <code>index</code>, and <code>source</code> stay in inputs.conf.",d:AD_MON,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"An Apache <code>access_combined</code> event whose raw timestamp includes an offset (e.g. <code>-0700</code>) is ingested via a monitor input. How does Splunk determine the event's time zone?",o:["From the <b>time-zone indicator (offset) in the raw event data</b>","From the <code>TZ</code> attribute in props.conf for the sourcetype","From the <code>TZ</code> attribute in props.conf for the host","From the time zone of the forwarder running the monitor input"],a:[0],e:"Time-zone precedence: an <b>explicit offset in the raw event wins</b>, then the <code>TZ</code> setting in props.conf, then the indexing instance's OS time zone. <code>access_combined</code> carries the offset, so Splunk uses it.",d:AD_TZ,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"What is the <b>minimum</b> required in inputs.conf to ingest data from a file or directory?",o:["A monitor stanza plus <code>sourcetype</code> and <code>index</code>","A monitor stanza plus <code>sourcetype</code>, <code>index</code>, and <code>host</code>","A monitor stanza plus <code>sourcetype</code>","Only the monitor stanza"],a:[3],e:"Only <code>[monitor://&lt;path&gt;]</code> is required. Splunk auto-detects the <b>sourcetype</b>, uses the <b>default index (main)</b>, and the <b>default host</b> — those are all optional overrides.",d:AD_MON,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"Which set contains only <b>valid</b> settings for a file/directory monitor input?",o:["<code>host, index, sourcetype, _TCP_Routing, host_regex, host_segment</code>","<code>host, index, source_length, _TCP_Routing, host_segment</code>","<code>host, index, directory, host_regex, host_segment</code>","<code>host, index, sourcetype, _UDP_Routing, host_regex, host_segment</code>"],a:[0],e:"Valid monitor settings include <code>host, index, sourcetype, _TCP_Routing, host_regex, host_segment</code>. <code>source_length</code>, <code>directory</code>, and <code>_UDP_Routing</code> are <b>not</b> real settings (routing is <code>_TCP_Routing</code>/<code>_SYSLOG_Routing</code>).",d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Inputsconf",hard:true},
 {exam:"cloudadmin",cat:"cloudover",q:"Which set describes features of a <b>managed</b> Splunk Cloud environment?",o:["Premium apps (ES/ITSI), SSO integration, and IP allow-list/deny-list control","Premium apps, but no IP allow-listing, and locked to the US-East AWS region","A 20 GB/day hard cap, no SSO, and no premium apps","Premium apps, SSO, and a fixed 20 concurrent-search limit"],a:[0],e:"Managed Splunk Cloud offers <b>premium apps</b> (ES/ITSI), <b>SSO (SAML)</b>, and <b>IP allow/deny lists</b> (via ACS). It isn't locked to one region and has no flat 20 GB cap or fixed search-concurrency limit.",d:CL_ACS,hard:true},
 {exam:"cloudadmin",cat:"cloudfwd",q:"How can you configure a <b>Universal Forwarder</b> as an intermediate forwarder?",o:["Only via Settings &gt; Forwarding and Receiving in Splunk Web","Via Splunk Web, CLI, config files, or a deployment app","Via CLI, config files, or a deployment app","Only by editing config files directly or via a deployment app"],a:[2],e:"A <b>UF has no Splunk Web/UI</b>, so the web menu isn't an option — configure it via <b>CLI, config files (inputs/outputs.conf), or a deployment app</b>. Any answer mentioning Splunk Web is wrong for a UF.",d:CL_FWD,hard:true},
 {exam:"cloudadmin",cat:"cloudsupport",q:"For a Splunk Cloud change request, who is the appropriate person to submit the Support case?",o:["Whoever requested the change","A Splunk-certified administrator","The Splunk infrastructure owner","Any person with the appropriate support entitlement"],a:[3],e:"Splunk Cloud Support cases are opened by an <b>authorized support contact — anyone with the appropriate entitlement</b>. It isn't tied to who requested the change or to holding a certification.",d:CL_SUPPORT,hard:true},
 /* --- added: from the official Splunk Cloud Administration course deck (v9.4) --- */
 {exam:"cloudadmin",cat:"cloudidx",q:"What is the maximum number of <b>active indexes</b> per Splunk Cloud environment?",o:["100 on both experiences","<b>400</b> on Classic, <b>1000</b> on Victoria","Unlimited","1000 on Classic, 400 on Victoria"],a:[1],e:"Max active indexes = <b>400 (Classic)</b> or <b>1000 (Victoria)</b>. Note: index data size is measured as the <b>uncompressed raw data</b>.",d:CL_MANIDX,hard:true},
 {exam:"cloudadmin",cat:"cloudidx",q:"Which is TRUE about Dynamic Data Active Archive (DDAA)?",o:["It's enabled by default and free","It's <b>disabled by default</b>, purchased from Splunk in <b>500 GB blocks</b> (contact Sales), and when full the <b>oldest buckets are deleted</b>","It stores data in the customer's own S3 bucket","It keeps data searchable indefinitely at no cost"],a:[1],e:"DDAA (Splunk-managed archive) is <b>off by default</b>, bought from Splunk in <b>500 GB blocks</b> (contact Sales), and evicts the <b>oldest buckets when full</b>. Restored data is searchable within ~24 hours.",d:CL_DDAA,hard:true},
 {exam:"cloudadmin",cat:"cloudidx",q:"Which is TRUE about Dynamic Data Self Storage (DDSS)?",o:["Splunk manages the archive for you","The <b>customer</b> purchases and manages it (AWS or GCP); to search archived data you <b>restore it to a customer-managed Splunk</b> instance","It keeps the data searchable in Splunk Cloud","It is identical to DDAA"],a:[1],e:"DDSS moves expired data to the <b>customer's own storage (AWS or GCP)</b> — not searchable in Cloud. To search it, you <b>restore to a customer-managed (on-prem) Splunk</b>. DDAA, by contrast, is Splunk-managed.",d:CL_MANIDX,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"The Splunk Cloud forwarder credentials package can enable <b>indexer acknowledgment</b>. What does it protect against?",o:["Duplicate events","<b>Loss of forwarded data</b> — if the forwarder receives no acknowledgment, it re-sends the data","Slow searches","License overage"],a:[1],e:"<b>Indexer acknowledgment</b> (<code>useACK</code>) guards against <b>data loss in transit</b>: if the forwarder doesn't get an ack that the data was written, it <b>re-sends</b> it.",d:CL_UFRECV,hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"In Splunk Cloud, what is the recommended way to mask, filter, or route data at ingest — the modern replacement for hand-editing <code>SEDCMD</code>/transforms?",o:["SSH in and edit props.conf/transforms.conf","<b>Ingest Actions</b> — build rulesets in Splunk Web to mask, truncate, filter, or route data","The <code>delete</code> command","A Support case for every rule"],a:[1],e:"<b>Ingest Actions</b> lets you build rulesets in <b>Splunk Web</b> to mask/truncate/filter/route data — the Cloud-native replacement for hand-editing <code>SEDCMD</code>/transforms (which you can't do without filesystem access).",d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/DataIngest",hard:true},
 {exam:"cloudadmin",cat:"cloudapps",q:"On the <b>Victoria</b> experience, installing an app requires a restart only when the app contains…",o:["Any app always requires a restart","<b>Static assets (logos/CSS/JS) or props and transforms</b>","Only dashboards","Nothing — restarts are never required"],a:[1],e:"Victoria cuts app restarts by ~90% — a restart is only needed when the app includes <b>static assets (logos, CSS, JS)</b> or <b>props and transforms</b>. Otherwise the install is seamless.",d:CL_PRIVAPP,hard:true},
 /* --- added: verified from external practice sets (unique, non-duplicate) + overlap with SPLK-1003 --- */
 {exam:"cloudadmin",cat:"cloudgdi",q:"What is the recommended approach to collect <b>syslog</b> data from network devices (routers, switches, firewalls) for Splunk Cloud?",o:["Point each device's TCP/UDP feed straight at a Cloud indexer","Send the TCP/UDP feed to a syslog server (rsyslog/syslog-ng) or SC4S, and have a <b>universal forwarder</b> read the resulting files","Feed devices into a heavy forwarder, then an intermediate forwarder, then Cloud","Upload the device logs through the Cloud UI Add Data page"],a:[1],e:"Network devices can't run a forwarder, and raw UDP straight into Splunk risks data loss. Best practice: land syslog on a dedicated <b>syslog server (rsyslog/syslog-ng)</b> or <b>Splunk Connect for Syslog (SC4S)</b>, write to files, and have a <b>UF</b> monitor and forward them.",d:"https://help.splunk.com/en/splunk-cloud-platform/splunk-validated-architectures/getting-data-in-forwarding-and-preprocessing/syslog-data-collection",hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"In Splunk Cloud (no filesystem/CLI access), what is used to create and preview a new <b>sourcetype</b>?",o:["<b>Data Preview</b> during the Add Data workflow in Splunk Web","Editing <code>props.conf</code> directly from the GUI","The Splunk CLI on an indexer","The deployment server"],a:[0],e:"Cloud gives no CLI/filesystem access. Use <b>Data Preview</b> (Add Data &rarr; Set Source Type) in Splunk Web to define, preview, and save a sourcetype. You can't hand-edit <code>props.conf</code> from the GUI, and the deployment server doesn't create sourcetypes.",d:CL_GDI,hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"Which <b>two</b> configuration files work together to perform an index-time data transformation (e.g. routing or masking with a regex)?",o:["<code>parsing.conf</code> and <code>transforms.conf</code>","<code>props.conf</code> and <code>transforms.conf</code>","<code>transforms.conf</code> and <code>fields.conf</code>","<code>transforms.conf</code> and <code>sourcetypes.conf</code>"],a:[1],e:"<code>props.conf</code> references the transform (<code>TRANSFORMS-...</code>) and <code>transforms.conf</code> defines the regex and action. A regex-based transform needs <b>both</b>; only <code>SEDCMD</code>-style masking lives in <code>props.conf</code> alone.",d:AD_ROUTE,hard:true},
 {exam:"cloudadmin",cat:"cloudfwd",q:"Which is a valid way to test whether a <b>forwarder</b> can successfully send data to Splunk Cloud?",o:["Search the <code>_audit</code> index to see if the forwarder ID was registered","Run a <b>oneshot</b> from the forwarder CLI, then search Cloud to confirm the events arrived","Use Add Data on the Cloud UI to upload a test file, then search for it","Ping <code>http-inputs-&lt;stack&gt;.splunkcloud.com</code> and check for a reply"],a:[1],e:"A CLI <b>oneshot</b> (<code>splunk add oneshot</code>) pushes a file through the forwarder's own output pipeline to Cloud, so finding those events proves the forwarder path works. The Add Data upload tests <b>Cloud ingest, not the forwarder</b>; ping only tests reachability.",d:AD_CLI,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"Windows inputs (event logs, WMI, performance metrics) are collected via a Splunk-provided, GUI-configurable input mechanism. What type of input is this?",o:["Batch","Scripted","Modular","Front-end"],a:[2],e:"Windows event log, WMI, and perfmon inputs are implemented as <b>modular inputs</b> — richer than plain scripted inputs and configurable through Splunk Web. (Batch is a one-time index-then-delete file input; there is no 'front-end' input type.)",d:AD_WINEVT,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"What is <b>Splunk Connect for Syslog (SC4S)</b>?",o:["A premium security app","A containerized <code>syslog-ng</code>-based collector Splunk recommends for scalable syslog ingestion","A replacement for the universal forwarder credentials package","The Cloud Monitoring Console"],a:[1],e:"<b>SC4S</b> is a container-based (<code>syslog-ng</code>) solution Splunk provides and recommends for reliably collecting syslog <b>at scale</b>, then forwarding to Splunk — an alternative to a plain rsyslog/syslog-ng + UF setup.",d:"https://help.splunk.com/en/splunk-cloud-platform/splunk-validated-architectures/getting-data-in-forwarding-and-preprocessing/syslog-data-collection",hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"Which single sign-on method does <b>Splunk Cloud Platform</b> support for enterprise authentication?",o:["LDAP directory binding","SAML-based SSO (e.g. Okta, Azure AD, PingID)","Local Splunk accounts only — no SSO","Kerberos"],a:[1],e:"Splunk Cloud supports <b>SAML SSO</b> (plus local Splunk auth, tokens, and MFA via DUO/RSA). <b>LDAP</b> — common on-prem — is <b>not</b> a Splunk Cloud authentication option, a frequent point of confusion.",d:AD_USERS,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"By default, when are most fields extracted from your data in Splunk?",o:["At index time, and stored in the index","At <b>search time</b>, when you run a search (schema-on-read)","Only when you build a data model","Never — you must define every field manually in <code>props.conf</code>"],a:[1],e:"Splunk extracts most fields at <b>search time</b> (schema-on-read), leaving the raw data untouched on disk. Only a small set — default fields and any explicit indexed extractions — is written at index time.",d:AD_GDI},
 {exam:"cloudadmin",cat:"cloudgdi",q:"Which set are Splunk's <b>default fields</b>, added to every event at index time?",o:["<code>host, source, sourcetype, index, _time</code>","<code>user, action, status, bytes</code>","<code>src_ip, dest_ip, port</code>","<code>app, owner, sharing, role</code>"],a:[0],e:"Every event gets <code>host</code>, <code>source</code>, <code>sourcetype</code>, <code>index</code>, and <code>_time</code> by default. The others are extracted at search time or supplied by add-ons/CIM, not automatically.",d:AD_GDI},
 {exam:"cloudadmin",cat:"cloudconf",q:"To index a file as <b>one event per line</b>, which <code>props.conf</code> settings are typically used?",o:["<code>LINE_BREAKER</code> and <code>SHOULD_LINEMERGE = false</code>","<code>TIME_PREFIX</code> and <code>TZ</code>","<code>KV_MODE</code> and <code>REPORT</code>","<code>INDEXED_EXTRACTIONS</code> only"],a:[0],e:"<code>LINE_BREAKER</code> defines where events split and <code>SHOULD_LINEMERGE = false</code> stops Splunk merging lines into multi-line events. These are <b>index-time</b> (parsing) settings, applied on an HF/IDM/indexer — not the UF.",d:AD_CONF,hard:true},
 {exam:"cloudadmin",cat:"cloudfwd",q:"How does a universal forwarder distribute data across multiple Splunk Cloud indexers?",o:["It sends everything to one indexer until it fills up","<b>Automatic load balancing (autoLB)</b> — it rotates across the indexers in its output group on a time interval","Round-robin only when the first indexer fails","It can't send to more than one indexer"],a:[1],e:"Forwarders use <b>automatic load balancing</b>, switching among the receivers in their <code>tcpout</code> target group on a timer (<code>autoLBFrequency</code>) so data spreads evenly. With Cloud, the credentials package configures this target for you.",d:CL_FWD,hard:true},
 {exam:"cloudadmin",cat:"cloudidx",q:"As data ages in a Splunk index, which is the correct <b>bucket</b> progression?",o:["cold &rarr; warm &rarr; hot &rarr; frozen","hot &rarr; warm &rarr; cold &rarr; frozen","warm &rarr; hot &rarr; frozen &rarr; cold","hot &rarr; cold &rarr; warm &rarr; frozen"],a:[1],e:"New data lands in <b>hot</b>, rolls to <b>warm</b>, then <b>cold</b>, then <b>frozen</b> (deleted or archived by default). In Cloud you don't manage buckets directly, but retention is governed by <b>searchable retention (days)</b> and <b>max size</b> — whichever hits first.",d:CL_MANIDX,hard:true},
 {exam:"cloudadmin",cat:"cloudconf",q:"Which <code>props.conf</code> setting tells Splunk <b>where the timestamp begins</b> in an event, improving parsing accuracy and speed?",o:["<code>TIME_PREFIX</code>","<code>LINE_BREAKER</code>","<code>KV_MODE</code>","<code>SEDCMD</code>"],a:[0],e:"<code>TIME_PREFIX</code> anchors where the timestamp starts; with <code>TIME_FORMAT</code> and <code>MAX_TIMESTAMP_LOOKAHEAD</code> it makes extraction precise. <code>LINE_BREAKER</code> handles event boundaries, <code>KV_MODE</code> is search-time extraction, <code>SEDCMD</code> masks raw data.",d:AD_TS,hard:true},
 {exam:"cloudadmin",cat:"cloudgdi",q:"A source is encoded in something other than UTF-8 and shows garbled characters. Which <code>props.conf</code> setting fixes it?",o:["<code>CHARSET</code>","<code>TZ</code>","<code>MAX_DAYS_AGO</code>","<code>BREAK_ONLY_BEFORE</code>"],a:[0],e:"<code>CHARSET</code> declares the source's character encoding (e.g. <code>CHARSET=UTF-16LE</code>) so Splunk converts it correctly to UTF-8 at index time. The others handle time zone, date bounds, and line breaking.",d:AD_CHARSET,hard:true},
 {exam:"cloudadmin",cat:"cloudover",q:"In Splunk Cloud, how do admins and users interact with the environment day to day?",o:["By SSHing into the indexers","Through <b>Splunk Web on the search head</b> (your <code>*.splunkcloud.com</code> URL) and the <b>ACS API</b> — the indexers aren't directly accessible","By RDP to the license manager","Only through Support tickets"],a:[1],e:"Users and admins work through <b>Splunk Web on the search head</b> and, for self-service admin, the <b>ACS API</b>. The underlying indexers and OS are Splunk-managed and not directly reachable — no SSH/CLI.",d:CL_GDI,hard:true}
];

/* ============ Cloud Admin Course — self-paced lessons mapped to the official course deck ============ */
function CLOUD_COURSE(){
 return [
  {key:'c1',cat:'cloudover',title:'Splunk Cloud Overview & Topology',modules:'Modules 1 & 14',blurb:'How Splunk Cloud is architected and who manages what.',doc:CL_GDI,
   summary:`<ul><li><b>Shared responsibility:</b> Splunk manages the indexers, search heads, and <b>platform upgrades</b>; you manage forwarders, inputs, and (if used) your own deployment server.</li>
   <li><b>No OS / CLI / filesystem access</b> — you administer via <b>Splunk Web</b>, the <b>Admin Config Service (ACS)</b>, or a <b>Support case</b>.</li>
   <li><b>Victoria vs Classic:</b> find yours under <b>Support &amp; Services &gt; About</b>; Splunk assigns it. Victoria runs inputs on the search head (no IDM); Classic requires an IDM.</li>
   <li><b>Four ways to get data in:</b> forwarders, HEC, apps/add-ons, and the IDM.</li>
   <li><b>Module 14 (Managing Cloud):</b> Federated Search, Private Connectivity (AWS), and self-service admin via ACS.</li></ul>`},
  {key:'c2',cat:'cloudgdi',title:'Getting Data Into Cloud',modules:'Modules 6, 8, 9, 10, 11',blurb:'Forwarders, HEC, IDM, and monitor inputs the Cloud way.',doc:CL_FWD,
   summary:`<ul><li><b>Connect a UF:</b> download the <code>splunkclouduf.spl</code> credentials package (Splunk Web &gt; Apps &gt; Universal Forwarder), install it, and restart. It carries outputs.conf + TLS certs; can enable <b>indexer acknowledgment</b> (re-sends on no-ack).</li>
   <li><b>UF vs HF:</b> a UF forwards unparsed data; <b>parsed/event data needs an HF or IDM</b>. Intermediate forwarders aggregate at ~<b>2:1</b> to Cloud indexers.</li>
   <li><b>IDM:</b> required on <b>Classic</b> for scripted/modular inputs; on <b>Victoria</b> those run on the search head.</li>
   <li><b>HEC on Cloud:</b> port <b>443</b>, with the <code>http-inputs-</code> hostname prefix.</li>
   <li><b>Monitor inputs:</b> only <code>[monitor://path]</code> is required; a raw-event <b>time-zone offset wins</b> over props.conf <code>TZ</code>.</li></ul>`},
  {key:'c3',cat:'cloudidx',title:'Index Management in Cloud',modules:'Module 3',blurb:'Creating indexes, retention, and the DDAS/DDAA/DDSS tiers.',doc:CL_MANIDX,
   summary:`<ul><li><b>Create indexes</b> in Splunk Web (Settings &gt; Indexes) or via <b>ACS</b> — never by editing <code>indexes.conf</code>.</li>
   <li><b>Retention</b> = Max raw data size + Searchable retention (days); data removed by whole buckets, oldest first. Max active indexes: <b>400 (Classic) / 1000 (Victoria)</b>.</li>
   <li><b>Data tiers:</b> DDAS (searchable) → then <b>DDAA</b> (Splunk-managed archive, 500&nbsp;GB blocks, restorable ~24h) or <b>DDSS</b> (your own AWS/GCP storage, restore to your own Splunk to search). Only one per index.</li>
   <li><b>Delete:</b> deleting an index is final; the <code>delete</code> command only hides events (doesn't free disk). Monitor with the <b>CMC</b>.</li></ul>`},
  {key:'c4',cat:'cloudconf',title:'Config & Admin Access (ACS)',modules:'Modules 2, 4, 13',blurb:'ACS, config without CLI, users/auth, and Ingest Actions.',doc:CL_ACS,
   summary:`<ul><li><b>No .conf editing:</b> change config via <b>Splunk Web</b>, the <b>ACS API/CLI</b>, or <b>Support</b>. ACS needs the <code>sc_admin</code> role + a bearer token and isn't supported on single-instance stacks.</li>
   <li><b>ACS self-service:</b> indexes, HEC tokens, IP allow lists, a <b>limits.conf subset</b> (Victoria), users/roles, apps, maintenance windows.</li>
   <li><b>Users &amp; auth:</b> roles → capabilities; the Cloud super-role is <code>sc_admin</code>; SAML is the common SSO.</li>
   <li><b>Ingest Actions (Module 13):</b> build rulesets in <b>Splunk Web</b> to <b>mask/truncate/filter/route</b> data — the Cloud-native replacement for hand-edited <code>SEDCMD</code>/transforms.</li></ul>`},
  {key:'c5',cat:'cloudapps',title:'Apps & Private Apps',modules:'Module 5',blurb:'Self-service install, AppInspect vetting, and premium apps.',doc:CL_INSTALL,
   summary:`<ul><li><b>Self-service install</b> (needs <code>sc_admin</code>) for most Splunkbase apps — must pass <b>AppInspect with 0 Failures / 0 Errors / 0 Manual Checks</b>.</li>
   <li><b>Premium apps (ES/ITSI)</b>, IDM installs, and &gt;0 manual checks require <b>Support</b>.</li>
   <li><b>Private apps:</b> <code>.spl/.tgz</code> ≤128&nbsp;MB, dynamic dependencies only; Cloud auto-runs AppInspect on upload.</li>
   <li><b>Victoria</b> auto-deploys apps to all search heads; a <b>restart is only needed</b> when the app has <b>static assets or props/transforms</b>. No self-service rollback.</li></ul>`},
  {key:'c6',cat:'cloudsupport',title:'Working with Cloud Support',modules:'Module 15',blurb:'Isolate first, then open a case the right way.',doc:CL_SUPPORT,
   summary:`<ul><li><b>Self-triage first:</b> use the <b>CMC</b> dashboards and search <code>index=_internal</code> / <code>index=_audit</code> to isolate the problem.</li>
   <li><b>Open cases</b> through the Splunk Support Portal; anyone with the <b>appropriate entitlement</b> can submit.</li>
   <li><b>Severity:</b> P1 (inaccessible) is 24×7; <b>Standard covers P1, Premium adds P2</b>.</li>
   <li><b>Needs Support:</b> premium-app installs/updates, IDM index sync (Classic), and config outside the ACS-editable subset.</li></ul>`},
  {key:'c7',cat:'cloudfwd',title:'Forwarder Management',modules:'Module 7',blurb:'Central management of forwarders in the Cloud model.',doc:CL_FWD,
   summary:`<ul><li><b>Splunk Cloud does NOT provide a deployment server</b> — the customer hosts one (on-prem or their own cloud) to manage forwarders.</li>
   <li>Push <code>splunkclouduf.spl</code> + inputs as <b>deployment-apps</b> from that deployment server to your forwarder clients.</li>
   <li>A <b>UF has no Splunk Web/UI</b> — configure it via <b>CLI, config files, or a deployment app</b> (not the web menu).</li></ul>`},
 ];
}
